/* Wedding invitation behaviour — ported verbatim from the original site's inline scripts
   (media data, EmailJS SDK v4.4.1 embedded, countdown/RSVP, YouTube fallback, main player/3D/scroll logic).
   One change for Next.js: LOCAL_MP3 now points to /assets/wedding-song.mp3 (public/assets)
   instead of the single-file export's embedded data URI. */

/* ===== Media: photos and fonts are embedded in this file. The wedding song,
   Swetha Sande by Yasas Medagedara, plays from the site's own MP3 asset —
   data:application/octet-stream;base64,, added by the site owner — and falls back to the
   same song streaming from YouTube when that file is absent. ===== */
window.__IMG_HERO = 'data:image/webp;base64,';
window.__IMG_DETAILS = 'data:image/webp;base64,';
window.__IMG_VENUE = 'data:image/webp;base64,';
(function(){
  var map = {hero: window.__IMG_HERO, details: window.__IMG_DETAILS, venue: window.__IMG_VENUE};
  document.querySelectorAll('img[data-asset]').forEach(function(img){ var k = img.getAttribute('data-asset'); if(map[k]) img.src = map[k]; });
})();

