(function(){
  // Countdown — Sun 6 Dec 2026, 10:00 AM Asia/Colombo (UTC+5:30)
  var target = new Date('2026-12-06T10:00:00+05:30').getTime();
  var dEl=document.getElementById('cd-d'),hEl=document.getElementById('cd-h'),mEl=document.getElementById('cd-m'),sEl=document.getElementById('cd-s');
  function pad(n){return String(n).padStart(2,'0')}
  var lastS='__';
  function setPop(el,val){ if(el.textContent!==String(val)){ el.textContent=val; el.classList.remove('pop'); void el.offsetWidth; el.classList.add('pop'); } }
  function tick(){
    var diff = target - Date.now();
    if(diff<=0){ dEl.textContent='0';hEl.textContent='00';mEl.textContent='00';sEl.textContent='00'; return; }
    var d=Math.floor(diff/86400000), h=Math.floor(diff%86400000/3600000), m=Math.floor(diff%3600000/60000), s=Math.floor(diff%60000/1000);
    setPop(dEl,d); setPop(hEl,pad(h)); setPop(mEl,pad(m)); if(String(s)!==lastS){ setPop(sEl,pad(s)); lastS=String(s); }
  }
  tick(); setInterval(tick,1000);

  // Stagger reveals inside each section + rich reveal on scroll
  document.querySelectorAll('section, .hero, .countdown').forEach(function(sec){
    var i=0; sec.querySelectorAll('.reveal').forEach(function(el){ el.style.setProperty('--i', i++); });
  });
  var reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var io = ('IntersectionObserver' in window) ? new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target)}})},{threshold:.05,rootMargin:'0px 0px 35% 0px'}) : null;
  document.querySelectorAll('.reveal').forEach(function(el){ if(io && !reduceMotion) io.observe(el); else el.classList.add('in'); });
  // Safety net: anything the observer hasn't reached shortly after load still gets its entrance.
  setTimeout(function(){ document.querySelectorAll('.reveal:not(.in)').forEach(function(el){ var r=el.getBoundingClientRect(); if(r.top < window.innerHeight*1.4) el.classList.add('in'); }); },1600);

  // --- Best scroll: progress, nav shadow, parallax, timeline line, back-to-top ---
  var prog=document.getElementById('scrollProgress'), nav=document.querySelector('.nav'), toTop=document.getElementById('toTop'),
      heroImg=document.getElementById('heroParallaxImg'), timeline=document.querySelector('.timeline'), ticking=false;
  function onScroll(){
    var y=window.scrollY||0, h=document.documentElement.scrollHeight-window.innerHeight;
    if(prog) prog.style.transform='scaleX('+(h>0?Math.min(1,y/h):0)+')';
    if(nav) nav.classList.toggle('scrolled', y>10);
    if(toTop) toTop.classList.toggle('show', y>560);
    if(heroImg && !reduceMotion && y<window.innerHeight*1.2) heroImg.style.transform='scale(1.08) translateY('+(y*0.045)+'px)';
    if(timeline && !reduceMotion){ var r=timeline.getBoundingClientRect(), vh=window.innerHeight, p=Math.max(0,Math.min(1,(vh*0.78-r.top)/Math.max(1,r.height))); timeline.style.setProperty('--line-p',p); }
    ticking=false;
  }
  window.addEventListener('scroll',function(){ if(!ticking){ ticking=true; requestAnimationFrame(onScroll); } },{passive:true});
  window.addEventListener('resize',function(){ if(!ticking){ ticking=true; requestAnimationFrame(onScroll); } },{passive:true});
  window.addEventListener('orientationchange',function(){ setTimeout(onScroll,120); });
  onScroll();
  if(toTop) toTop.addEventListener('click',function(){ window.scrollTo({top:0,behavior:reduceMotion?'auto':'smooth'}); });

  // --- 3D tilt (pointer devices only) ---
  if(!reduceMotion && window.matchMedia('(hover:hover) and (pointer:fine)').matches){
    document.querySelectorAll('.tilt').forEach(function(card){
      var raf=null;
      card.addEventListener('pointermove',function(e){
        var r=card.getBoundingClientRect(), px=(e.clientX-r.left)/r.width-.5, py=(e.clientY-r.top)/r.height-.5;
        if(raf) cancelAnimationFrame(raf);
        raf=requestAnimationFrame(function(){ card.style.transform='perspective(1100px) rotateY('+(px*10)+'deg) rotateX('+(-py*10)+'deg) translateY(-4px)'; });
      });
      card.addEventListener('pointerleave',function(){ if(raf) cancelAnimationFrame(raf); card.style.transform=''; });
    });
  }

  // Add to calendar (.ics download)
  function downloadICS(){
    var ics = ['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Wedding Invite//EN','BEGIN:VEVENT',
      'UID:akash-amiduni-20261206@wedding','DTSTAMP:20261126T090000Z',
      'DTSTART:20261206T043000Z','DTEND:20261206T113000Z',
      'SUMMARY:Akash & Amiduni — Wedding','LOCATION:Hotel Heritage\\, Badulla',
      'DESCRIPTION:Poruwa ceremony at 10:00 AM followed by lunch reception.','END:VEVENT','END:VCALENDAR'].join('\r\n');
    var blob = new Blob([ics],{type:'text/calendar'});
    var a=document.createElement('a'); a.href=URL.createObjectURL(blob); a.download='Akash-and-Amiduni-Wedding.ics';
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(function(){URL.revokeObjectURL(a.href)},2000);
  }
  document.getElementById('calBtn').addEventListener('click',downloadICS);
  document.getElementById('icsBtn2').addEventListener('click',downloadICS);

  // Guest stepper
  var count=2, out=document.getElementById('gCount');
  document.getElementById('gMinus').addEventListener('click',function(){ if(count>1){count--; out.textContent=count;} });
  document.getElementById('gPlus').addEventListener('click',function(){ if(count<10){count++; out.textContent=count;} });

  // Attending toggle dims guest fields when declining
  var attendFields=document.getElementById('attendFields');
  document.querySelectorAll('input[name="attend"]').forEach(function(r){
    r.addEventListener('change',function(){
      var declines = document.querySelector('input[name="attend"]:checked').value.indexOf('Declines')>-1;
      attendFields.style.opacity = declines ? '.4' : '1';
      attendFields.style.pointerEvents = declines ? 'none' : 'auto';
    });
  });

  /* ================================================================
     EMAILJS CONFIG — activated with the site owner's EmailJS keys.
     RSVPs are sent straight from this page via EmailJS
     (https://www.emailjs.com) — the guest stays on the site and no
     email app ever opens. The delivery address is set by the
     "To Email" field inside the EmailJS template; the to_email
     param below matches it: rashmikaakash001@gmail.com.
       Service: service_uxiabj7 · Template: template_a79qy9s
       Template variables sent: {{title}}, {{name}}, {{attending}},
       {{guests}}, {{phone}}, {{meal}}, {{message}} and {{time}}
       (time = submission timestamp).
     The SDK is embedded in this file (no CDN to fail), and sending
     retries through both the SDK and a direct EmailJS API call.
     On success the guest sees an on-site thank-you; on failure a
     clear error with a retry — the form never opens an email app.
     ================================================================ */
  var EMAILJS_PUBLIC_KEY  = '6lg9fOLGDJ5c0ipsd';
  var EMAILJS_SERVICE_ID  = 'service_uxiabj7';
  var EMAILJS_TEMPLATE_ID = 'template_a79qy9s';
  var RSVP_TO_EMAIL = 'rashmikaakash001@gmail.com';

  function emailjsConfigured(){
    return EMAILJS_PUBLIC_KEY.indexOf('YOUR_')!==0 &&
           EMAILJS_SERVICE_ID.indexOf('YOUR_')!==0 &&
           EMAILJS_TEMPLATE_ID.indexOf('YOUR_')!==0;
  }

  /* --- RSVP sending engine -------------------------------------------------
     Two independent paths to the same EmailJS account, retried in turn:
       Path 1 — the embedded EmailJS SDK above (window.emailjs).
       Path 2 — a direct POST to the EmailJS API (https://api.emailjs.com),
                the exact endpoint and payload the SDK itself uses, so the
                RSVP still sends even if the SDK object is unavailable.
     Transient failures (network error, timeout, 429, 5xx) are retried up to
     3 attempts with a short pause. Permanent rejections from EmailJS
     (400 / 403 / 404 / 412 / 422 — bad key, blocked origin, template or
     service problem) stop early and surface EmailJS's own error text, so
     the exact reason is visible instead of a vague failure.
     ------------------------------------------------------------------------- */
  function withTimeout(promise, ms){
    return Promise.race([promise, new Promise(function(resolve, reject){
      setTimeout(function(){ reject({status:0, text:'The request timed out'}); }, ms);
    })]);
  }
  function sendViaSdk(params){
    try{ window.emailjs.init({ publicKey: EMAILJS_PUBLIC_KEY }); }catch(e){}
    return window.emailjs.send(EMAILJS_SERVICE_ID, EMAILJS_TEMPLATE_ID, params);
  }
  function sendViaApi(params){
    var ctrl = ('AbortController' in window) ? new AbortController() : null;
    var timer = ctrl ? setTimeout(function(){ try{ ctrl.abort(); }catch(e){} }, 15000) : null;
    return fetch('https://api.emailjs.com/api/v1.0/email/send', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        lib_version: '4.4.1',
        user_id: EMAILJS_PUBLIC_KEY,
        service_id: EMAILJS_SERVICE_ID,
        template_id: EMAILJS_TEMPLATE_ID,
        template_params: params
      }),
      signal: ctrl ? ctrl.signal : undefined
    }).then(function(res){
      if(timer) clearTimeout(timer);
      return res.text().then(function(txt){
        if(res.ok) return { status: res.status, text: txt };
        throw { status: res.status, text: txt };
      });
    }, function(err){
      if(timer) clearTimeout(timer);
      throw { status: 0, text: (err && err.name === 'AbortError') ? 'The request timed out' : 'Network Error' };
    });
  }
  function isPermanentRsvpError(err){
    var s = err && err.status;
    return s===400 || s===403 || s===404 || s===412 || s===422;
  }
  function sendRsvp(params){
    var methods = [];
    if(typeof window.emailjs !== 'undefined') methods.push(sendViaSdk);
    methods.push(sendViaApi);
    var lastErr = { status: 0, text: 'Network Error' };
    function attempt(i){
      if(i >= 3) return Promise.reject(lastErr);
      var fn = methods[i % methods.length];
      return withTimeout(Promise.resolve().then(function(){ return fn(params); }), 20000)
        .catch(function(err){
          lastErr = err || lastErr;
          if(isPermanentRsvpError(lastErr)) throw lastErr;
          return new Promise(function(res){ setTimeout(res, 1200 * (i + 1)); })
            .then(function(){ return attempt(i + 1); });
        });
    }
    return attempt(0);
  }

  // RSVP — sent in the background via EmailJS; guest stays on the site
  var form=document.getElementById('rsvpForm');
  var submitBtn=document.getElementById('rsvpSubmit');
  form.addEventListener('submit',function(ev){
    ev.preventDefault();
    var name=document.getElementById('guestName').value.trim();
    var contact=document.getElementById('guestPhone').value.trim();
    var status=document.querySelector('input[name="attend"]:checked').value;
    var meal=document.getElementById('meal').value;
    var song=document.getElementById('song').value.trim();
    var box=document.getElementById('confirmBox');
    var title=document.getElementById('confirmTitle');
    var text=document.getElementById('confirmText');
    function showBox(){ box.classList.add('show'); box.scrollIntoView({behavior:'smooth',block:'center'}); }
    if(!name){
      title.textContent='One small thing…';
      text.textContent='Please add your name so the couple knows who this RSVP is from — then tap Send My RSVP again.';
      showBox(); return;
    }
    var declines = status.indexOf('Declines')>-1;
    var summary = 'Name: '+name+'\nResponse: '+status;
    if(!declines){ summary += '\nGuests: '+count+'\nMeal: '+meal; }
    if(contact) summary += '\nContact: '+contact;
    if(song) summary += '\nMessage: '+song;

    if(!emailjsConfigured()){
      title.textContent='Hmm, that didn’t go through';
      text.textContent='The RSVP email is not set up on this copy of the site yet, so nothing was sent. Please let Akash & Amiduni know.';
      showBox(); return;
    }
    if(submitBtn.disabled) return;

    submitBtn.disabled=true;
    var originalLabel=submitBtn.textContent;
    submitBtn.textContent='Sending…';
    var templateParams = {
      to_email: RSVP_TO_EMAIL,
      title: 'New RSVP — Akash & Amiduni Wedding',
      name: name,
      from_name: name,
      from_email: contact,
      reply_to: contact,
      to_name: 'Akash & Amiduni',
      attending: status,
      guests: declines ? 0 : count,
      phone: contact,
      meal: declines ? '' : meal,
      // The full RSVP rides inside {{message}} too, so the email is complete
      // even if the EmailJS template only prints {{name}} / {{message}} / {{time}}.
      message: song ? (song + '\n\n— RSVP details —\n' + summary) : summary,
      rsvp_details: summary,
      time: new Date().toLocaleString('en-GB', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric', hour: 'numeric', minute: '2-digit', hour12: true })
    };
    sendRsvp(templateParams).then(function(){
      title.textContent = declines ? 'You will be missed, '+name.split(' ')[0]+'.' : 'Thank you, '+name.split(' ')[0]+'!';
      text.textContent = summary + '\n\nYour RSVP has been sent to Akash & Amiduni — no email app needed. We can\u2019t wait to celebrate with you!';
      submitBtn.textContent='RSVP Sent ✓';
      showBox();
    }, function(err){
      if(window.console && console.error) console.error('RSVP send failed:', err);
      var detail = '';
      if(err && err.status){ detail = ' (EmailJS error ' + err.status + (err.text ? ': ' + String(err.text).slice(0,140) : '') + ')'; }
      title.textContent='Hmm, that didn’t go through';
      if(isPermanentRsvpError(err)){
        text.textContent='Your RSVP could not be sent — the email service reported a problem' + detail + '. Your answers are still filled in above, so please tap Send My RSVP to try once more. If it keeps happening, please show this message to Akash & Amiduni so they can check the RSVP email setup.';
      }else{
        text.textContent='Your RSVP could not be sent just now — please check your connection and tap Send My RSVP to try again. Your answers are still filled in above.' + detail;
      }
      submitBtn.disabled=false;
      submitBtn.textContent=originalLabel;
      showBox();
    });
  });
})();

