  /* If the API never arrives (offline / blocked), mark YouTube unavailable so the players show a tap-to-retry message */
  setTimeout(function(){ if(!window.__ytSong.apiReady){ window.__ytSong.failed = true; if(window.__onYTSongError) window.__onYTSongError(); } }, 12000);

