(function(){
  var reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var audio = document.getElementById('weddingAudio');
  var dock = document.getElementById('musicDock');
  var playBtn = document.getElementById('playBtn');
  var progFill = document.getElementById('musicProgFill');
  var vol = document.getElementById('musicVol');
  var overlay = document.getElementById('welcomeOverlay');
  var toastEl = document.getElementById('toast');
  var userPaused = false;
  var toastTimer = null;
  /* Default song volume: 20% (guests can still change it with either player's slider) */
  if(audio) audio.volume = 0.2;

  /* ===== Song transport: Swetha Sande plays from the site's own MP3 first.
     The track ships with the site as data:application/octet-stream;base64,, and the
     audio element loads it directly — instant start, seekable, works
     without YouTube. The file is loaded through the <audio> element
     itself, never probed with fetch(): browsers block fetch() on
     file:// pages, which would wrongly report a present MP3 as
     missing when the owner opens the downloaded page from his PC.
     Instead, an audio 'error' (or a rejected play()) is what marks
     the MP3 unusable and hands over to the SAME song on YouTube.
     If neither source can start, the players show a tap-to-retry
     state — a different song is never played instead. ===== */
  var LOCAL_MP3 = '/assets/wedding-song.mp3';
  var songMode = 'none'; /* becomes 'local' (own MP3) or 'youtube' once a source starts */
  var localState = 'unknown'; /* 'unknown' -> 'checking' (audio element loading) -> 'ready' (can play) | 'missing' */
  var ytPlaying = false, loopOn = true, ytWatch = null;
  var srcEl = document.getElementById('playerSrc');
  function setSrcLabel(){
    if(!srcEl) return;
    srcEl.textContent = localState === 'ready'
      ? 'Playing from this site\u2019s own MP3 file — fast start, no buffering'
      : (localState === 'missing'
          ? 'Streaming from YouTube'
          : (localState === 'checking'
              ? 'Loading the site\u2019s own music file\u2026'
              : 'Plays from this site\u2019s own MP3 file \u00B7 YouTube backup'));
  }
  /* The local MP3 is declared unusable only by the audio element itself:
     an 'error' event or a load-related play() rejection (see startLocal
     and the error listener below). fetch() is never used to check for
     the file — it is blocked on file:// pages even when the MP3 sits
     right next to the HTML, which used to force a needless YouTube
     fallback for the downloaded copy. Once the MP3 is marked missing,
     hand over to the same song on YouTube (waiting briefly if the
     YouTube player is still loading). */
  function localFailed(){
    if(localState === 'missing') return;
    localState = 'missing'; setSrcLabel();
    if(songMode === 'local') songMode = 'none';
    startYouTubeWhenReady();
  }
  function ytObj(){ return window.__ytSong || null; }
  function ytAvailable(){ var Y = ytObj(); return !!(Y && Y.ready && Y.player && !Y.failed); }
  function ytState(){ var Y = ytObj(); if(!Y || !Y.player || !Y.player.getPlayerState) return -99; try{ return Y.player.getPlayerState(); }catch(e){ return -99; } }
  function srcPlaying(){ if(songMode === 'youtube') return ytPlaying; return !!(audio && !audio.paused); }
  function srcTime(){ if(songMode === 'youtube'){ var Y = ytObj(); if(Y && Y.player && Y.player.getCurrentTime){ try{ return Y.player.getCurrentTime() || 0; }catch(e){} } return 0; } return audio ? (audio.currentTime || 0) : 0; }
  function srcDur(){ if(songMode === 'youtube'){ var Y = ytObj(); if(Y && Y.player && Y.player.getDuration){ try{ return Y.player.getDuration() || 0; }catch(e){} } return 0; } return audio ? (audio.duration || 0) : 0; }
  function srcPause(){ var Y = ytObj(); if(Y && Y.player && Y.player.pauseVideo){ try{ Y.player.pauseVideo(); }catch(e){} } if(audio && !audio.paused) audio.pause(); }
  function srcSeek(t){ if(songMode === 'youtube'){ var Y = ytObj(); if(Y && Y.player && Y.player.seekTo){ try{ Y.player.seekTo(t, true); }catch(e){} return; } } if(audio) audio.currentTime = t; }
  function srcSetVolume(v){ var Y = ytObj(); if(Y && Y.player && Y.player.setVolume){ try{ Y.player.setVolume(Math.round(v * 100)); if(v === 0){ if(Y.player.mute) Y.player.mute(); } else if(Y.player.unMute) Y.player.unMute(); }catch(e){} } if(audio) audio.volume = v; }
  function showSongRetry(){
    var Y = ytObj(); if(Y && Y.player && Y.player.pauseVideo){ try{ Y.player.pauseVideo(); }catch(e){} }
    ytPlaying = false;
    if(audio && !audio.paused) audio.pause();
    songMode = 'none';
    setPlayingUI();
    try{ syncPlayer(); }catch(e){}
    if(pStatus) pStatus.textContent = 'Swetha Sande could not load — check your connection, then tap play to try again';
    toast('Swetha Sande could not load — tap play to try again');
  }
  function watchYtStart(){
    clearTimeout(ytWatch);
    ytWatch = setTimeout(function(){
      if(songMode !== 'youtube') return;
      var st = ytState();
      /* 1 = playing, 3 = buffering: on its way. Anything else after 8s means it did not start */
      if(st !== 1 && st !== 3) showSongRetry();
    }, 8000);
  }
  window.__onYTSongReady = function(){ try{ syncPlayer(); }catch(e){} setPlayingUI(); };
  window.__onYTSongError = function(){ if(songMode === 'youtube') showSongRetry(); };
  window.__onYTSongState = function(state){
    /* YT states: 0 ended, 1 playing, 2 paused, 3 buffering, 5 cued */
    if(state === 1){ ytPlaying = true; clearTimeout(ytWatch); }
    else if(state === 2 || state === 5){ ytPlaying = false; }
    else if(state === 0){
      ytPlaying = false;
      if(songMode === 'youtube' && loopOn){ srcSeek(0); var Y = ytObj(); if(Y && Y.player){ try{ Y.player.playVideo(); }catch(e){} } }
      else if(songMode === 'youtube' && pStatus) pStatus.textContent = 'Finished — tap play to hear it again';
    }
    setPlayingUI();
    try{ syncPlayer(); }catch(e){}
  };

  function toast(msg){
    toastEl.textContent = msg;
    toastEl.classList.add('show');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function(){ toastEl.classList.remove('show'); }, 3400);
  }
  function setPlayingUI(){
    var playing = srcPlaying();
    dock.classList.toggle('playing', !!playing);
    playBtn.setAttribute('aria-label', playing ? 'Pause Swetha Sande' : 'Play Swetha Sande');
  }
  /* Primary source: the owner's own MP3 in the assets folder. It starts
     instantly and supports real seeking; YouTube is paused while it plays. */
  function startLocal(){
    songMode = 'local';
    var Y = ytObj(); if(Y && Y.player && Y.player.pauseVideo){ try{ Y.player.pauseVideo(); }catch(e){} }
    ytPlaying = false;
    if(!audio.getAttribute('src')) audio.src = LOCAL_MP3;
    audio.volume = (vol ? vol.value : 20) / 100;
    var p = audio.play();
    if(p && p.catch) p.catch(function(err){
      /* A load/support failure means the MP3 cannot be used: fall back
         to the YouTube stream. An autoplay-policy block
         (NotAllowedError) is NOT a file problem — the next tap retries
         the MP3, so it must not trigger the fallback. */
      if(err && err.name === 'NotAllowedError'){ setPlayingUI(); return; }
      localFailed();
    });
    setPlayingUI();
    try{ syncPlayer(); }catch(e){}
  }
  function startYouTube(){
    songMode = 'youtube';
    if(audio && !audio.paused) audio.pause();
    var Y = ytObj();
    try{ Y.player.setVolume(Math.round((vol ? vol.value : 20))); }catch(e){}
    try{ Y.player.playVideo(); }catch(e){ showSongRetry(); return; }
    watchYtStart();
    setPlayingUI();
    try{ syncPlayer(); }catch(e){}
  }
  var ytWaitTimer = null;
  /* Stream the same song from YouTube. If the player is still loading,
     wait for it briefly; if it never becomes ready (or already failed),
     show the tap-to-retry state — a different song is never played. */
  function startYouTubeWhenReady(){
    if(ytAvailable()){ startYouTube(); return; }
    var Y = ytObj();
    if(Y && Y.failed){ showSongRetry(); return; }
    if(pStatus) pStatus.textContent = 'Loading Swetha Sande…';
    toast('Loading Swetha Sande…');
    var tries = 0;
    clearInterval(ytWaitTimer);
    ytWaitTimer = setInterval(function(){
      tries++;
      if(ytAvailable()){ clearInterval(ytWaitTimer); startYouTube(); }
      else if(tries >= 20){ clearInterval(ytWaitTimer); showSongRetry(); }
    }, 500);
  }
  function playSong(){
    /* 1) Own MP3 first — the fast path the owner asked for. The audio
       element loads data:application/octet-stream;base64, directly (this also works
       from a file:// page, where fetch() would be blocked); a 'canplay'
       event confirms it, an 'error' hands over to YouTube. A repeat tap
       while it is still loading simply re-issues play(). */
    if(localState === 'ready' || localState === 'checking'){ startLocal(); return; }
    if(localState === 'unknown'){
      localState = 'checking'; setSrcLabel();
      if(pStatus) pStatus.textContent = 'Loading Swetha Sande…';
      startLocal();
      return;
    }
    /* 2) The MP3 already proved unusable: YouTube streams the same song. */
    startYouTubeWhenReady();
  }
  /* No MP3 request is made on page load: the audio element only loads
     the file inside playSong(), on the first press of play. */
  /* Once the MP3 can actually play, it is confirmed as the source. */
  audio.addEventListener('canplay', function(){
    if(localState === 'checking'){ localState = 'ready'; setSrcLabel(); }
  });
  /* If the local file errors (missing / unreadable / unsupported),
     fall back to YouTube once. This audio error — never a fetch
     failure — is the trigger for the fallback. */
  audio.addEventListener('error', function(){
    if(songMode === 'local') localFailed();
  }, true);
  function burst(x, y){
    if(reduceMotion) return;
    for(var i=0;i<26;i++){
      var s = document.createElement('span');
      s.className = 'burst-petal';
      var ang = Math.random()*Math.PI*2, dist = 90 + Math.random()*190;
      s.style.left = x+'px'; s.style.top = y+'px';
      s.style.setProperty('--tx', Math.cos(ang)*dist+'px');
      s.style.setProperty('--ty', (Math.sin(ang)*dist - 60)+'px');
      s.style.setProperty('--rot', (Math.random()*420-210)+'deg');
      document.body.appendChild(s);
      (function(el){ setTimeout(function(){ el.remove(); }, 1600); })(s);
    }
  }

  /* Welcome opening */
  document.documentElement.classList.add('locked');
  function closeWelcome(withMusic, ev){
    overlay.classList.add('hide');
    document.documentElement.classList.remove('locked');
    dock.classList.add('show');
    if(withMusic){
      userPaused = false;
      playSong();
      toast('Now playing — Swetha Sande · Yasas Medagedara');
      if(ev && ev.clientX) burst(ev.clientX, ev.clientY);
      else burst(window.innerWidth/2, window.innerHeight/2);
    }
    setTimeout(function(){ overlay.style.display = 'none'; }, 900);
  }
  document.getElementById('openInviteBtn').addEventListener('click', function(ev){ closeWelcome(true, ev); });
  document.getElementById('skipMusicBtn').addEventListener('click', function(ev){ userPaused = true; closeWelcome(false, ev); });

  /* Music dock controls */
  playBtn.addEventListener('click', function(){
    if(!srcPlaying()){ userPaused = false; playSong(); }
    else { userPaused = true; srcPause(); setPlayingUI(); try{ syncPlayer(); }catch(e){} }
  });
  if(vol) vol.addEventListener('input', function(){ setVolume(vol.value/100); });
  audio.addEventListener('play', setPlayingUI);
  audio.addEventListener('pause', setPlayingUI);
  audio.addEventListener('timeupdate', function(){
    if(songMode !== 'youtube' && audio.duration) progFill.style.width = (audio.currentTime/audio.duration*100)+'%';
  });

  /* ===== Full song player (test player) — shares the same audio element ===== */
  var player = document.getElementById('songPlayer');
  var pPlayBtn = document.getElementById('playerPlayBtn');
  var seekBar = document.getElementById('seekBar');
  var timeCur = document.getElementById('timeCur');
  var timeTot = document.getElementById('timeTot');
  var pStatus = document.getElementById('playerStatus');
  var pVol = document.getElementById('playerVol');
  var muteBtn = document.getElementById('muteBtn');
  var loopBtn = document.getElementById('loopBtn');
  var speedSel = document.getElementById('speedSel');
  var scrubbing = false, lastVol = 0.2;
  function fmt(t){
    if(!isFinite(t) || t < 0) return '–:––';
    var m = Math.floor(t/60), s = Math.floor(t%60);
    return m + ':' + (s < 10 ? '0' : '') + s;
  }
  function syncPlayer(){
    var playing = srcPlaying();
    var dur = srcDur(), cur = srcTime();
    player.classList.toggle('playing', playing);
    pPlayBtn.setAttribute('aria-label', playing ? 'Pause the wedding song' : 'Play the wedding song');
    if(!scrubbing && dur) seekBar.value = Math.round(cur/dur*1000);
    if(progFill && dur) progFill.style.width = (cur/dur*100)+'%';
    timeCur.textContent = fmt(cur);
    timeTot.textContent = fmt(dur);
    pStatus.textContent = playing
      ? 'Now playing — Swetha Sande · Yasas Medagedara'
      : (cur > 0.05 && dur && cur < dur - 0.05
          ? 'Paused at ' + fmt(cur) + ' — tap play to continue'
          : 'Ready — tap play to hear Swetha Sande');
  }
  pPlayBtn.addEventListener('click', function(){
    if(!srcPlaying()){ userPaused = false; playSong(); }
    else { userPaused = true; srcPause(); setPlayingUI(); syncPlayer(); }
  });
  document.getElementById('restartBtn').addEventListener('click', function(){
    srcSeek(0); userPaused = false; playSong(); syncPlayer();
  });
  document.getElementById('backBtn').addEventListener('click', function(){
    srcSeek(Math.max(0, srcTime() - 10)); syncPlayer();
  });
  document.getElementById('fwdBtn').addEventListener('click', function(){
    var d = srcDur(); if(d) srcSeek(Math.min(d, srcTime() + 10)); syncPlayer();
  });
  seekBar.addEventListener('input', function(){
    scrubbing = true;
    if(srcDur()){
      var t = seekBar.value/1000 * srcDur();
      timeCur.textContent = fmt(t);
      pStatus.textContent = 'Jump to ' + fmt(t);
    }
  });
  seekBar.addEventListener('change', function(){
    if(srcDur()) srcSeek(seekBar.value/1000 * srcDur());
    scrubbing = false; syncPlayer();
  });
  function setVolume(v){
    srcSetVolume(v);
    pVol.value = Math.round(v*100);
    if(vol) vol.value = Math.round(v*100);
    muteBtn.classList.toggle('muted', v === 0);
    muteBtn.setAttribute('aria-label', v === 0 ? 'Unmute the song' : 'Mute the song');
  }
  pVol.addEventListener('input', function(){ setVolume(pVol.value/100); if(pVol.value > 0) lastVol = pVol.value/100; });
  if(vol) vol.addEventListener('input', function(){ setVolume(vol.value/100); if(vol.value > 0) lastVol = vol.value/100; });
  muteBtn.addEventListener('click', function(){
    if(audio.volume > 0){ lastVol = audio.volume; setVolume(0); }
    else setVolume(lastVol || 0.2);
  });
  loopBtn.addEventListener('click', function(){
    loopOn = !loopOn;
    audio.loop = loopOn;
    var Y = ytObj(); if(Y && Y.player && Y.player.setLoop){ try{ Y.player.setLoop(loopOn); }catch(e){} }
    loopBtn.classList.toggle('on', loopOn);
    loopBtn.setAttribute('aria-pressed', String(loopOn));
    toast(loopOn ? 'Loop on — the song will repeat' : 'Loop off — the song plays once');
  });
  speedSel.addEventListener('change', function(){
    audio.playbackRate = parseFloat(speedSel.value);
    var Y = ytObj(); if(Y && Y.player && Y.player.setPlaybackRate){ try{ Y.player.setPlaybackRate(parseFloat(speedSel.value)); }catch(e){} }
    toast('Playback speed ' + speedSel.value + '×');
  });
  audio.addEventListener('play', syncPlayer);
  audio.addEventListener('pause', syncPlayer);
  audio.addEventListener('timeupdate', syncPlayer);
  audio.addEventListener('loadedmetadata', syncPlayer);
  audio.addEventListener('ended', function(){ pStatus.textContent = 'Finished — tap play to hear it again'; syncPlayer(); });
  syncPlayer();
  /* YouTube has no timeupdate event — poll its clock so seek/progress stay live */
  setInterval(function(){ if(songMode === 'youtube') syncPlayer(); }, 500);
  /* If the browser allows it, begin softly on the very first touch anywhere */
  document.addEventListener('pointerdown', function once(){
    document.removeEventListener('pointerdown', once);
    if(!userPaused && overlay.classList.contains('hide') === false) return;
    if(!userPaused && !srcPlaying() && overlay.style.display === 'none') playSong();
  });

  /* Gallery lightbox */
  var figs = Array.prototype.slice.call(document.querySelectorAll('.g-grid figure'));
  var lb = document.getElementById('lightbox'), lbImg = document.getElementById('lbImg'), lbCap = document.getElementById('lbCap'), idx = 0;
  function showLb(i){
    idx = (i + figs.length) % figs.length;
    var img = figs[idx].querySelector('img'), cap = figs[idx].querySelector('figcaption');
    lbImg.src = img.src; lbImg.alt = img.alt || '';
    lbCap.textContent = cap ? cap.textContent : '';
    lb.hidden = false; document.documentElement.classList.add('locked');
  }
  function hideLb(){ lb.hidden = true; document.documentElement.classList.remove('locked'); }
  figs.forEach(function(f, i){
    f.setAttribute('tabindex','0'); f.setAttribute('role','button'); f.setAttribute('aria-label','View photo larger');
    f.addEventListener('click', function(){ showLb(i); });
    f.addEventListener('keydown', function(e){ if(e.key === 'Enter' || e.key === ' '){ e.preventDefault(); showLb(i); } });
  });
  document.getElementById('lbClose').addEventListener('click', hideLb);
  document.getElementById('lbPrev').addEventListener('click', function(e){ e.stopPropagation(); showLb(idx-1); });
  document.getElementById('lbNext').addEventListener('click', function(e){ e.stopPropagation(); showLb(idx+1); });
  lb.addEventListener('click', function(e){ if(e.target === lb) hideLb(); });
  document.addEventListener('keydown', function(e){
    if(lb.hidden) return;
    if(e.key === 'Escape') hideLb();
    if(e.key === 'ArrowLeft') showLb(idx-1);
    if(e.key === 'ArrowRight') showLb(idx+1);
  });

  /* Guest wishes wall (this visit only) */
  var wishForm = document.getElementById('wishForm'), wall = document.getElementById('wishWall');
  wishForm.addEventListener('submit', function(ev){
    ev.preventDefault();
    var name = document.getElementById('wishName').value.trim();
    var msg = document.getElementById('wishMsg').value.trim();
    if(!name || !msg){ toast('Please add your name and a short wish first.'); return; }
    var empty = document.getElementById('wishEmpty'); if(empty) empty.remove();
    var card = document.createElement('div'); card.className = 'wish-card';
    var from = document.createElement('div'); from.className = 'w-from'; from.textContent = name;
    var p = document.createElement('p'); p.textContent = msg;
    card.appendChild(from); card.appendChild(p);
    wall.insertBefore(card, wall.firstChild);
    wishForm.reset();
    toast('Thank you, ' + name.split(' ')[0] + ' — your wish is on the wall!');
    card.scrollIntoView({behavior: reduceMotion ? 'auto' : 'smooth', block: 'nearest'});
  });

  /* Scrollspy — highlight the section you're reading */
  var spyLinks = {};
  document.querySelectorAll('.nav-links a[href^="#"]').forEach(function(a){ spyLinks[a.getAttribute('href').slice(1)] = a; });
  if('IntersectionObserver' in window){
    var spy = new IntersectionObserver(function(es){
      es.forEach(function(e){
        if(e.isIntersecting){
          Object.keys(spyLinks).forEach(function(k){ spyLinks[k].classList.remove('active'); });
          if(spyLinks[e.target.id]) spyLinks[e.target.id].classList.add('active');
        }
      });
    }, {rootMargin: '-38% 0px -55% 0px'});
    ['story','details','schedule','gallery','song-player','wishes'].forEach(function(id){
      var el = document.getElementById(id); if(el) spy.observe(el);
    });
  }
})();
